/**
 * Data access for the C Programming course. Loaders only — every rule lives in
 * `core/learning/ccourse.ts`, and every artifact is generated by `scripts/c-course.cjs`.
 */
import { useEffect, useState } from 'react';
import type { CAssessmentSet, CCourseFile, CIndex, CInterviewItem, CLab, CProject } from '../learning/ccourse';

const cache = new Map<string, Promise<unknown>>();

function load<T>(file: string): Promise<T> {
  const key = file;
  if (!cache.has(key)) {
    cache.set(key, fetch(`generated/c-course/${file}`).then((r) => {
      if (!r.ok) throw new Error(`c-course/${file}: ${r.status}`);
      return r.json() as Promise<T>;
    }).catch((err) => { cache.delete(key); throw err; }));
  }
  return cache.get(key) as Promise<T>;
}

export function useCIndex(): CIndex | null {
  const [data, setData] = useState<CIndex | null>(null);
  useEffect(() => { let live = true; load<CIndex>('index.json').then((d) => live && setData(d)).catch(() => {}); return () => { live = false; }; }, []);
  return data;
}

export function useCCourse(): CCourseFile | null {
  const [data, setData] = useState<CCourseFile | null>(null);
  useEffect(() => { let live = true; load<CCourseFile>('course.json').then((d) => live && setData(d)).catch(() => {}); return () => { live = false; }; }, []);
  return data;
}

